 if nonref>=10 and nonref/d>.08: print('"'BASE',p+1,offset+p+1,ref[p],dict(c))
for p,c in sorted(events.items()):
 if sum(c.values())>=5:print('INDEL',p+1,offset+p+1,ref[p-8:p+14],dict(c))
